result.output:
100				pidStr := "unknown"
101				if holder := lockfile.ReadHolderPID(lockPath); holder > 0 {
102					pidStr = strconv.Itoa(holder)
103				}
104				fmt.Fprintf(cmd.ErrOrStderr(),
105					"another `entire %s` is already running (PID %s, lock at %s); refusing to start a second instance\n",
106					opName, pidStr, lockPath)
107				return nil, NewSilentError(fmt.Errorf("%s already in progress", opName))
108			}
109			cmd.SilenceUsage = true
110			return nil, fmt.Errorf("acquire %s lock: %w", opName, err)
111		}
112	
113		return func() {
114			if relErr := lk.Release(); relErr != nil {
115				logging.Warn(ctx, "failed to release command lock",
116					slog.String("op", opName),
117					slog.String("error", relErr.Error()))
118			}
119		}, nil
120	}
