248	// migrateCheckpointsV2 returns the /full/<n> refs migration wrote so callers
249	// can pass them as exclusions to the generation-metadata repair pass.
250	func migrateCheckpointsV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, progressOut io.Writer, force bool) (*migrateResult, []plumbing.ReferenceName, error) {
251		v1List, err := v1Store.ListCommitted(ctx)
252		if err != nil {
253			return nil, nil, fmt.Errorf("failed to list v1 checkpoints: %w", err)
254		}
255	
256		if len(v1List) == 0 {
257			return &migrateResult{}, nil, nil
258		}
259	
260		sortMigratableCheckpoints(v1List)
261		total := len(v1List)
262		result := &migrateResult{total: total}
263		progress := startProgressBar(progressOut, "Migrating checkpoints", total)
264		defer progress.Finish()
265	
266		_, fullCurrentRefErr := repo.Reference(plumbing.ReferenceName(paths.V2FullCurrentRefName), true)
267		fullCurrentExistsBefore := fullCurrentRefErr == nil
268	
269		// One up-front tree walk to make per-session "are /full/* artifacts
270		// present?" checks O(1) inside the migration loop.
271		fullArtifactsIndex, err := v2Store.BuildFullSessionArtifactsIndex()
272		if err != nil {
273			return nil, nil, fmt.Errorf("build v2 /full/* presence index: %w", err)
274		}
275	
276		batchSize := migrateFullBatchSize()
277		pendingFull := make([]migratedFullCheckpoint, 0, batchSize)
278		var writtenRefs []plumbing.ReferenceName
279		nextGeneration := 0
280	
281		for _, info := range v1List {
282			fullCheckpoint, outcome, migrateErr := migrateOneCheckpoint(ctx, repo, v1Store, v2Store, info, force, fullArtifactsIndex)
283			result.missingSessions += outcome.missingSessions
284			if outcome.compactTranscriptSkipped {
285				result.compactTranscriptSkipped++
286			}
287	
288			if migrateErr != nil {
289				switch {
290				case errors.Is(migrateErr, errAlreadyMigrated):
291					logCheckpointMigrationSkip(ctx, info.CheckpointID, "already in v2", migrateErr)
292					result.skipped++
293				case errors.Is(migrateErr, errNoMigratableSessions):
294					logCheckpointMigrationSkip(ctx, info.CheckpointID, "no migratable v1 sessions", migrateErr)
295					result.skipped++
296				default:
297					logging.Error(ctx, "checkpoint migration failed",
298						slog.String("checkpoint_id", string(info.CheckpointID)),
299						slog.String("error", migrateErr.Error()),
300					)
301					result.failed++
302				}
303				progress.Increment()
304				continue
305			}
306	
307			if fullCheckpoint != nil {
308				pendingFull = append(pendingFull, *fullCheckpoint)
309				if len(pendingFull) == batchSize {
310					if nextGeneration == 0 {
311						// Resolve the archive slot only when the first full batch is ready;
312						// force migration may prune existing archived refs earlier in the loop.
313						next, nextErr := v2Store.NextGenerationNumber()
314						if nextErr != nil {
315							return result, writtenRefs, fmt.Errorf("list archived v2 generations: %w", nextErr)
316						}
317						nextGeneration = next
318					}
319					refName := checkpoint.ArchivedGenerationRefName(nextGeneration)
320					if packErr := writeMigratedFullGeneration(ctx, repo, refName, pendingFull); packErr != nil {
321						return result, writtenRefs, fmt.Errorf("failed to pack migrated raw transcripts: %w", packErr)
322					}
323					writtenRefs = append(writtenRefs, refName)
324					nextGeneration++
325					pendingFull = make([]migratedFullCheckpoint, 0, batchSize)
326				}
327			}
328			result.migrated++
329			progress.Increment()
330		}
331	
332		progress.Finish()
333		stopFinalize := startSpinner(progressOut, "Packing migrated raw transcripts")
334		if len(pendingFull) > 0 {
335			if err := writeMigratedFinalFullCurrent(ctx, repo, v2Store, pendingFull); err != nil {
336				stopFinalize(false)
337				return result, writtenRefs, fmt.Errorf("failed to pack migrated raw transcripts: %w", err)
338			}
339			// If /full/current already had checkpoints, this final migration write can
340			// briefly push the generation past the threshold before rotation. That
341			// mirrors other v2 ref-merge cases where a generation may exceed the soft
342			// threshold by a small amount.
343			if refName, rotated, err := v2Store.RotateCurrentGenerationIfNeeded(ctx, batchSize); err != nil {
344				stopFinalize(false)
345				return result, writtenRefs, fmt.Errorf("failed to rotate migrated full/current generation: %w", err)
346			} else if rotated {
347				writtenRefs = append(writtenRefs, refName)
348			}
349		} else if len(writtenRefs) > 0 && !fullCurrentExistsBefore {
350			if err := ensureEmptyV2FullCurrent(ctx, repo); err != nil {
351				stopFinalize(false)
352				return result, writtenRefs, fmt.Errorf("failed to pack migrated raw transcripts: %w", err)
353			}
354		}
355		stopFinalize(true)
356	
357		return result, writtenRefs, nil
358	}
