360	func logCheckpointMigrationSkip(ctx context.Context, checkpointID id.CheckpointID, reason string, err error) {
361		logging.Info(ctx, "checkpoint migration skipped",
362			slog.String("checkpoint_id", string(checkpointID)),
363			slog.String("reason", reason),
364			slog.String("error", err.Error()),
365		)
366	}
