529	func writeMigratedFinalFullCurrent(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, checkpoints []migratedFullCheckpoint) error {
530		if len(checkpoints) == 0 {
531			return nil
532		}
533	
534		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
535		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
536		if err != nil && !errors.Is(err, plumbing.ErrReferenceNotFound) {
537			return fmt.Errorf("read v2 full/current ref: %w", err)
538		}
539	
540		entries := make(map[string]object.TreeEntry)
541		if rootTreeHash != plumbing.ZeroHash {
542			rootTree, err := repo.TreeObject(rootTreeHash)
543			if err != nil {
544				return fmt.Errorf("read v2 full/current tree: %w", err)
545			}
546			if err := checkpoint.FlattenTree(repo, rootTree, "", entries); err != nil {
547				return fmt.Errorf("flatten v2 full/current tree: %w", err)
548			}
549			delete(entries, paths.GenerationFileName)
550		}
551	
552		// Evict any pre-existing raw transcript artifacts for the sessions we're
553		// about to write so a shrinking chunk count can't leave stale .N files
554		// behind from a prior migration of the same checkpoint.
555		for _, cp := range checkpoints {
556			for _, session := range cp.sessions {
557				evictMigratedRawArtifacts(entries, cp.checkpointID, session.sessionIndex)
558			}
559		}
560		pendingEntries, err := buildMigratedFullEntrySet(ctx, repo, checkpoints)
561		if err != nil {
562			return fmt.Errorf("write migrated full/current entries: %w", err)
563		}
564		pendingEntries.mergeInto(entries)
565	
566		treeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
567		if err != nil {
568			return fmt.Errorf("build migrated full/current tree: %w", err)
569		}
570	
571		commitHash, err := checkpoint.CreateCommit(ctx, repo, treeHash, parentHash,
572			"Write migrated partial generation\n",
573			migrateAuthorName, migrateAuthorEmail)
574		if err != nil {
575			return fmt.Errorf("create migrated full/current commit: %w", err)
576		}
577	
578		return updateV2FullCurrentRef(ctx, repo, parentHash, commitHash)
579	}
580	
581	func updateV2FullCurrentRef(ctx context.Context, repo *git.Repository, expectedHash, newHash plumbing.Hash) error {
582		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
583		newRef := plumbing.NewHashReference(refName, newHash)
584		if expectedHash == plumbing.ZeroHash {
585			return createV2FullCurrentRefIfMissing(ctx, repo, refName, newHash)
586		}
587	
588		oldRef := plumbing.NewHashReference(refName, expectedHash)
589		if err := repo.Storer.CheckAndSetReference(newRef, oldRef); err != nil {
590			return fmt.Errorf("update %s: %w", refName, err)
591		}
592		return nil
593	}
594	
595	func createV2FullCurrentRefIfMissing(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, newHash plumbing.Hash) error {
596		root, err := repoWorktreeRoot(repo)
597		if err != nil {
598			return fmt.Errorf("resolve worktree root for %s update: %w", refName, err)
599		}
600	
601		cmd := exec.CommandContext(ctx, "git", "update-ref", "--no-deref", refName.String(), newHash.String(), "")
602		cmd.Dir = root
603		output, err := cmd.CombinedOutput()
604		if err == nil {
605			return nil
606		}
607	
608		if currentRef, refErr := repo.Reference(refName, true); refErr == nil {
609			if currentRef.Hash() == newHash {
610				return nil
611			}
612			return fmt.Errorf("update %s: %w", refName, storage.ErrReferenceHasChanged)
613		}
614		if len(output) > 0 {
615			return fmt.Errorf("update %s: %w: %s", refName, err, strings.TrimSpace(string(output)))
616		}
617		return fmt.Errorf("update %s: %w", refName, err)
618	}
619	
620	func repoWorktreeRoot(repo *git.Repository) (string, error) {
621		worktree, err := repo.Worktree()
622		if err != nil {
623			return "", fmt.Errorf("open worktree: %w", err)
624		}
625		root := worktree.Filesystem.Root()
626		if root == "" {
627			return "", errors.New("repository worktree filesystem has no root path")
628		}
629		return root, nil
630	}
631	
632	func writeMigratedFullGeneration(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, checkpoints []migratedFullCheckpoint) error {
633		fullEntries, err := buildMigratedFullEntrySet(ctx, repo, checkpoints)
634		if err != nil {
635			return fmt.Errorf("write migrated generation entries: %w", err)
636		}
637	
638		entries := make(map[string]object.TreeEntry, len(fullEntries.rawEntries)+len(fullEntries.taskEntries))
639		fullEntries.mergeInto(entries)
640		treeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
641		if err != nil {
642			return fmt.Errorf("build migrated generation tree: %w", err)
643		}
644	
645		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
646		// Reuse the transcripts already in memory rather than walking the tree
647		// we just built — same first/last-event range, no redundant blob reads.
648		gen, found := checkpoint.AggregateTranscriptTimestamps(migratedTranscripts(checkpoints))
649		if !found {
650			var err error
651			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
652			if err != nil {
653				return fmt.Errorf("compute checkpoint timestamps: %w", err)
654			}
655		}
656		if !found {
657			gen, found = generationMetadataFromMigratedSessions(checkpoints)
658		}
659		if !found {
660			return fmt.Errorf("no timestamps found for migrated generation %s", refName)
