753	func buildMigratedFullSessionEntrySet(ctx context.Context, repo *git.Repository, cp migratedFullCheckpoint, session migratedFullSession) (migratedFullEntrySet, error) {
754		sessionPath := fmt.Sprintf("%s/%d/", cp.checkpointID.Path(), session.sessionIndex)
755		transcript := session.content.Transcript
756		rawHashPath := sessionPath + paths.V2RawTranscriptHashFileName
757		var entries migratedFullEntrySet
758	
759		chunks, err := agent.ChunkTranscript(ctx, transcript, session.content.Metadata.Agent)
760		if err != nil {
761			return migratedFullEntrySet{}, fmt.Errorf("chunk transcript: %w", err)
762		}
763		for i, chunk := range chunks {
764			blobHash, blobErr := checkpoint.CreateBlobFromContent(repo, chunk)
765			if blobErr != nil {
766				return migratedFullEntrySet{}, fmt.Errorf("create transcript blob: %w", blobErr)
767			}
768			path := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
769			entries.rawEntries = append(entries.rawEntries, object.TreeEntry{
770				Name: path,
771				Mode: filemode.Regular,
772				Hash: blobHash,
773			})
774		}
775	
776		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
777		hashBlob, err := checkpoint.CreateBlobFromContent(repo, []byte(contentHash))
778		if err != nil {
779			return migratedFullEntrySet{}, fmt.Errorf("create transcript hash blob: %w", err)
780		}
781		entries.rawEntries = append(entries.rawEntries, object.TreeEntry{
782			Name: rawHashPath,
783			Mode: filemode.Regular,
784			Hash: hashBlob,
785		})
786	
787		for _, taskTreeHash := range cp.taskTrees[session.sessionIndex] {
788			taskTree, treeErr := repo.TreeObject(taskTreeHash)
789			if treeErr != nil {
790				return migratedFullEntrySet{}, fmt.Errorf("read task metadata tree: %w", treeErr)
791			}
792			taskEntries := make(map[string]object.TreeEntry)
793			if flattenErr := checkpoint.FlattenTree(repo, taskTree, sessionPath+"tasks", taskEntries); flattenErr != nil {
794				return migratedFullEntrySet{}, fmt.Errorf("flatten task metadata tree: %w", flattenErr)
795			}
796			for _, entry := range taskEntries {
797				entries.taskEntries = append(entries.taskEntries, entry)
798			}
799		}

800	
801		return entries, nil
802	}
